    if not input_data:
        return

    n = int(input_data[0])
    h = [int(x) for x in input_data[1:n+1]]

    left = 0
    right = n - 1
    left_max = 0
    right_max = 0
    covered_sections = 0

    while left < right:
        if h[left] < h[right]:
            if h[left] >= left_max:
